import {M3_WIDTH,M3_HEIGHT,M3_COLORS,m3Adjacent,m3Goals,m3Hint,m3Move} from './match3.mjs';

export function createMatch3UI({root,asset,onChange,onExit,onClaim,onRetry,onSound}){
  const q=selector=>root.querySelector(selector),reduced=matchMedia('(prefers-reduced-motion: reduce)'),powerNames={row:'横向火箭',col:'竖向火箭',bomb:'炸弹',orb:'彩球'};
  let session=null,chosen=null,focused=0,hammerMode=false,hints=[],panel=null,locked=false,pointer=null,ignoreClickUntil=0,shown=false;
  const imageFor=p=>asset(p.power?`m3-${p.power==='row'?'rocket-row':p.power==='col'?'rocket-col':p.power}`:`m3-${M3_COLORS[p.color].id}`);
  const goalImage=g=>asset(g.kind==='mud'?'m3-mud':`m3-${M3_COLORS[g.color].id}`);
  const goalName=g=>g.kind==='mud'?'泥地':M3_COLORS[g.color].name;
  const arrow='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m14 5-7 7 7 7M7 12h13"/></svg>';
  root.innerHTML=`<header class="m3-header"><button class="m3-round" data-m3-action="back" aria-label="保存三消进度并返回地图">${arrow}</button><div><small id="m3-region"></small><h1 id="m3-level"></h1></div><button class="m3-round" data-m3-action="help" aria-label="三消玩法说明">?</button></header>
    <section class="m3-objectives" aria-label="关卡目标与剩余步数"><div class="m3-objective-copy"><small>收集目标</small><div id="m3-goals" class="m3-goals" aria-live="polite"></div></div><div class="m3-moves"><strong id="m3-moves"></strong><small>剩余步数</small></div></section>
    <div class="m3-reward-note"><img src="${asset('chest')}" alt=""><span id="m3-purpose"></span><b>通关 ×1 箱</b></div>
    <div class="m3-board-area"><div id="m3-board" class="m3-board" role="grid" aria-label="七列八行三消棋盘" aria-rowcount="8" aria-colcount="7"></div><div id="m3-board-fx" class="m3-board-fx" aria-hidden="true"></div></div>
    <div id="m3-status" class="m3-status" role="status" aria-live="polite"></div>
    <div class="m3-tools"><button data-m3-action="hint"><span class="m3-tool-icon">✦</span><span>提示<small>找一对可交换的棋子</small></span></button><button id="m3-hammer" data-m3-action="hammer"><img src="${asset('m3-hammer')}" alt=""><span>小锤 <b id="m3-hammer-count">1</b><small>敲掉一格，不扣步数</small></span></button></div>
    <footer class="m3-footer"><span id="m3-score">得分 0</span><button data-m3-action="restart">重开本关</button><span id="m3-save">进度自动保存</span></footer>
    <div id="m3-panel" class="m3-panel" hidden><div id="m3-panel-card" class="m3-panel-card" role="dialog" aria-modal="true" aria-label="三消关卡结果"></div></div>`;

  function status(text,kind=''){q('#m3-status').textContent=text;q('#m3-status').className='m3-status '+kind;}
  function hud(override={}){const game={...session.game,...override};q('#m3-level').textContent=`第 ${game.level} 关`;q('#m3-region').textContent=`${session.region==='camp'?'林间营地':'芦苇河湾'} · 第 ${session.winsBefore+1} 箱物资`;q('#m3-moves').textContent=game.moves;q('.m3-moves').classList.toggle('low',game.moves<=5);q('#m3-goals').innerHTML=m3Goals(game).map(g=>`<div class="m3-goal${g.done?' done':''}" aria-label="${goalName(g)}，${g.done?'已完成':'还差'+g.remaining}"><img src="${goalImage(g)}" alt=""><div><strong>${g.done?'✓':g.remaining}</strong><small>${goalName(g)}</small></div></div>`).join('');q('#m3-hammer-count').textContent=game.hammer;q('#m3-hammer').disabled=!game.hammer||locked;q('#m3-hammer').classList.toggle('active',hammerMode);q('#m3-score').textContent=`得分 ${game.score}`;}
  function board(game=session.game){
    const hadFocus=document.activeElement?.matches?.('[data-m3-index]');let html='';for(let row=0;row<M3_HEIGHT;row++){html+=`<div class="m3-row" role="row">`;for(let col=0;col<M3_WIDTH;col++){const i=row*M3_WIDTH+col,p=game.board[i],name=p?(p.power?powerNames[p.power]:M3_COLORS[p.color].name):'空位';html+=`<button class="m3-cell${game.mud[i]?' muddy':''}${chosen===i?' selected':''}${hints.includes(i)?' hinted':''}${p?.power?' special':''}" role="gridcell" aria-rowindex="${row+1}" aria-colindex="${col+1}" aria-selected="${chosen===i}" aria-label="第 ${row+1} 行第 ${col+1} 列，${name}${game.mud[i]?'，下方有泥地':''}" data-m3-index="${i}" data-color="${p?.color??''}" data-power="${p?.power||''}" data-m3-hint="${hints.includes(i)}" tabindex="${focused===i?0:-1}">${game.mud[i]?`<img class="m3-mud" src="${asset('m3-mud')}" alt="">`:''}${p?`<span class="m3-token" data-token-id="${p.id}"><img src="${imageFor(p)}" alt="" draggable="false"></span>`:''}</button>`;}html+='</div>';}q('#m3-board').innerHTML=html;if(hadFocus)q(`[data-m3-index="${focused}"]`)?.focus({preventScroll:true});
  }
  function showPanel(){
    for(const section of root.querySelectorAll('.m3-header,.m3-objectives,.m3-reward-note,.m3-board-area,.m3-status,.m3-tools,.m3-footer'))section.inert=!!panel;
    if(!panel){q('#m3-panel').hidden=true;return;}const game=session.game,goals=m3Goals(game);let html='';
    if(panel==='help')html=`<small class="m3-eyebrow">一起找回重建材料</small><h2>交换、消除、带物资回家</h2><p>拖动交换相邻棋子，或依次点两格。三个相同棋子连成横排或竖排即可消除，未形成消除不会扣步数。</p><div class="m3-power-help"><span><img src="${asset('m3-rocket-row')}" alt="">四连：火箭</span><span><img src="${asset('m3-bomb')}" alt="">T / L 形：炸弹</span><span><img src="${asset('m3-orb')}" alt="">五连：彩球</span></div><p>点击道具直接触发，拖到相邻道具可组合。彩球与普通棋子交换，会消除同色棋子。泥地需要在它上方消除一次。</p><p>小锤每局免费一次，不扣步数。通关后才获得素材箱；失败可以免费重试。</p><button class="m3-panel-primary" data-m3-action="resume">开始动手</button>`;
    else if(panel==='restart')html=`<small class="m3-eyebrow">重新挑战</small><h2>换个开局，再试一次？</h2><p>这一局的棋盘和步数会重置，地图上的素材、建筑和已获物资都会保留。</p><button class="m3-panel-primary" data-m3-action="retry">重新开始本关</button><button class="m3-panel-secondary" data-m3-action="resume">继续这一局</button>`;
    else if(game.status==='won')html=`<div class="m3-win-seal">✓</div><small class="m3-eyebrow">第 ${game.level} 关 · 目标全部完成</small><h2>物资找齐了！</h2><img class="m3-prize" src="${asset('chest')}" alt="素材箱"><div class="m3-prize-label">${session.region==='camp'?'营地':'河湾'}素材箱 ×1</div><p>还剩 ${game.moves} 步 · 本关 ${game.score} 分<br>把这一箱带回去，继续修好我们的故乡。</p><button class="m3-panel-primary" data-m3-action="claim">带回素材箱</button>`;
    else html=`<small class="m3-eyebrow">第 ${game.level} 关 · 步数用完了</small><h2>还差一点点</h2><div class="m3-unfinished">${goals.filter(g=>!g.done).map(g=>`<span><img src="${goalImage(g)}" alt="">还差 ${g.remaining} ${goalName(g)}</span>`).join('')}</div><p>这次没有获得素材箱。再挑战一次，地图上的建设进度会保留。</p><button class="m3-panel-primary" data-m3-action="retry">免费重试</button><button class="m3-panel-secondary" data-m3-action="back">先回地图</button>`;
    q('#m3-panel-card').innerHTML=html;q('#m3-panel').hidden=false;q('#m3-panel-card').setAttribute('aria-label',panel==='result'?(game.status==='won'?'三消通关成功':'三消挑战未完成'):'三消说明');q('#m3-panel-card button')?.focus({preventScroll:true});
  }
  function render(){hud();board();showPanel();root.classList.toggle('m3-busy',locked);root.classList.toggle('m3-hammer-mode',hammerMode);}
  function setLocked(value){locked=value;root.classList.toggle('m3-busy',value);for(const button of root.querySelectorAll('.m3-header button,.m3-tools button,.m3-footer button'))button.disabled=value;hud();}
  async function animate(nodes,keyframes,options){if(reduced.matches)return;await Promise.all(nodes.filter(Boolean).map(node=>node.animate(keyframes,{duration:options?.duration||140,easing:'ease-out',...options}).finished.catch(()=>{})));}
  async function swapMotion(a,b,reverse=false){const nodes=[q(`[data-m3-index="${a}"] .m3-token`),q(`[data-m3-index="${b}"] .m3-token`)];if(!nodes[0]||!nodes[1]||reduced.matches)return;const ar=nodes[0].getBoundingClientRect(),br=nodes[1].getBoundingClientRect(),dx=br.left-ar.left,dy=br.top-ar.top;await Promise.all(nodes.map((node,i)=>node.animate([{transform:'translate(0,0)'},{transform:`translate(${i?-dx:dx}px,${i?-dy:dy}px)`}],{duration:reverse?130:155,easing:'ease-in-out',fill:'forwards'}).finished.catch(()=>{})));}
  function blasts(frame){if(!frame.activated?.length&&!frame.combo)return;const fx=q('#m3-board-fx');fx.innerHTML='';for(const p of frame.activated){const effect=document.createElement('span'),cell=q(`[data-m3-index="${p.index}"]`).getBoundingClientRect(),area=q('.m3-board-area').getBoundingClientRect();if(p.power==='row'||p.power==='col'){effect.className=`m3-beam ${p.power}`;if(p.power==='row')effect.style.top=`${cell.top-area.top+cell.height/2}px`;else effect.style.left=`${cell.left-area.left+cell.width/2}px`;}else{const size=cell.width*(p.power==='bomb'?3.1:4);effect.className=`m3-pulse ${p.power}`;Object.assign(effect.style,{left:`${cell.left-area.left+cell.width/2-size/2}px`,top:`${cell.top-area.top+cell.height/2-size/2}px`,width:`${size}px`,height:`${size}px`});}fx.appendChild(effect);}if(frame.combo){fx.innerHTML='<span class="m3-combo-flash"></span>';status(frame.combo,'combo');}}
  async function playFrames(result){
    for(const frame of result.frames){
      if(frame.type==='swap'){await swapMotion(frame.a,frame.b);board({...session.game,...frame});}
      else if(frame.type==='clear'){blasts(frame);if(!frame.combo){if(frame.made.length)status(`合出了${powerNames[frame.made[0].power]}！`,'combo');else if(frame.wave>1)status(`${frame.wave} 连消！`,'combo');else if(frame.activated.length)status(`${powerNames[frame.activated[0].power]}出发！`,'combo');}onSound?.(frame.made.length?'growth':'merge');await animate(frame.indices.map(i=>q(`[data-m3-index="${i}"] .m3-token`)),[{transform:'scale(1)',opacity:1},{transform:'scale(1.18)',opacity:1,offset:.25},{transform:'scale(.18)',opacity:0}],{duration:150});hud(frame);board({...session.game,...frame});q('#m3-board-fx').innerHTML='';}
      else if(frame.type==='drop'){board({...session.game,...frame});if(!reduced.matches){const animations=[];for(const fall of frame.falls){if(fall.from===fall.to)continue;const token=q(`[data-token-id="${fall.id}"]`);if(!token)continue;const cell=token.closest('.m3-cell').getBoundingClientRect(),dy=(Math.floor(fall.from/M3_WIDTH)-Math.floor(fall.to/M3_WIDTH))*(cell.height+3);animations.push(token.animate([{transform:`translateY(${dy}px)`,opacity:fall.from<0?.15:1},{transform:'translateY(0)',opacity:1}],{duration:190,easing:'cubic-bezier(.25,.65,.4,1.1)'}).finished.catch(()=>{}));}await Promise.all(animations);}}
      else if(frame.type==='shuffle'){status('没有可用交换，免费重新排列了棋盘');board({...session.game,...frame});await animate([q('#m3-board')],[{opacity:.35},{opacity:1}],{duration:220});}
    }
  }
  async function action(move){
    if(locked||!shown||panel||!session)return;const result=m3Move(session.game,move),destination=move.type==='SWAP'?move.b:move.index;if(Number.isInteger(destination)&&destination>=0&&destination<M3_WIDTH*M3_HEIGHT)focused=destination;chosen=null;hints=[];hammerMode=false;setLocked(true);
    if(!result.ok){if(result.frames[0]?.type==='swap'){const frame=result.frames[0];await swapMotion(frame.a,frame.b);board({...session.game,board:frame.board});await swapMotion(frame.a,frame.b,true);}setLocked(false);render();status(result.message,'error');return;}
    session={...session,game:result.state};const saved=onChange(session);q('#m3-save').textContent=saved===false?'本局暂未保存':'进度已保存';try{await playFrames(result);}finally{setLocked(false);panel=session.game.status==='playing'?null:'result';render();}
    if(session.game.status==='won')onSound?.('build');else if(session.game.status==='playing'&&result.waves<=1)status('继续收集目标，火箭和炸弹可以直接点。');
  }
  function choose(index){if(locked||panel||!session||session.game.status!=='playing')return;focused=index;hints=[];if(hammerMode){action({type:'HAMMER',index});return;}if(session.game.board[index].power){action({type:'ACTIVATE',index});return;}if(chosen===index){chosen=null;board();return;}if(chosen!==null&&m3Adjacent(chosen,index)){action({type:'SWAP',a:chosen,b:index});return;}chosen=index;board();status('再点一个相邻棋子交换，也可以直接滑动。');}
  function command(name){if(locked||!session)return;
    if(name==='back'){hammerMode=false;onExit();}
    else if(name==='claim'){if(session.game.status!=='won')return;q('[data-m3-action="claim"]').disabled=true;onClaim(session);}
    else if(name==='retry'){onRetry(session);}
    else if(name==='resume'){panel=session.game.status==='playing'?null:'result';render();if(!panel)q(`[data-m3-index="${focused}"]`)?.focus({preventScroll:true});}
    else if(name==='help'){panel='help';showPanel();}
    else if(name==='restart'){panel='restart';showPanel();}
    else if(name==='hammer'&&session.game.hammer){hammerMode=!hammerMode;chosen=null;hints=[];render();status(hammerMode?'点一格使用小锤，本次不扣步数。':'小锤已收起。');}
    else if(name==='hint'){const hint=m3Hint(session.game);if(!hint)return;chosen=null;hammerMode=false;hints=hint.type==='SWAP'?[hint.a,hint.b]:[hint.index];render();status(hint.type==='SWAP'?'交换发光的两格试试看。':'点击发光的道具，可以消除一大片。');}
  }
  root.addEventListener('click',event=>{const control=event.target.closest('[data-m3-action]');if(control){command(control.dataset.m3Action);return;}if(performance.now()<ignoreClickUntil)return;const cell=event.target.closest('[data-m3-index]');if(cell)choose(Number(cell.dataset.m3Index));});
  q('#m3-board').addEventListener('pointerdown',event=>{if(locked||panel||pointer||event.button!==0||event.isPrimary===false)return;const cell=event.target.closest('[data-m3-index]');if(!cell)return;pointer={index:Number(cell.dataset.m3Index),id:event.pointerId,x:event.clientX,y:event.clientY,cell,moved:false};cell.setPointerCapture(event.pointerId);});
  q('#m3-board').addEventListener('pointermove',event=>{if(!pointer||pointer.id!==event.pointerId)return;const dx=event.clientX-pointer.x,dy=event.clientY-pointer.y;if(Math.hypot(dx,dy)>10)pointer.moved=true;if(pointer.moved){const token=pointer.cell.querySelector('.m3-token');if(token)token.style.transform=`translate(${Math.max(-35,Math.min(35,dx))}px,${Math.max(-35,Math.min(35,dy))}px)`;}});
  q('#m3-board').addEventListener('pointerup',event=>{if(!pointer||pointer.id!==event.pointerId)return;const p=pointer;pointer=null;p.cell.querySelector('.m3-token')?.style.removeProperty('transform');if(p.cell.hasPointerCapture(event.pointerId))p.cell.releasePointerCapture(event.pointerId);if(!p.moved)return;ignoreClickUntil=performance.now()+400;if(hammerMode){choose(p.index);return;}const dx=event.clientX-p.x,dy=event.clientY-p.y,other=p.index+(Math.abs(dx)>Math.abs(dy)?Math.sign(dx):Math.sign(dy)*M3_WIDTH);action({type:'SWAP',a:p.index,b:other});});
  q('#m3-board').addEventListener('pointercancel',()=>{pointer?.cell.querySelector('.m3-token')?.style.removeProperty('transform');pointer=null;});
  root.addEventListener('keydown',event=>{if(panel&&event.key==='Tab'){const buttons=[...q('#m3-panel-card').querySelectorAll('button:not(:disabled)')],first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}return;}if(event.key==='Escape'){event.preventDefault();event.stopPropagation();if(locked)return;if(panel==='help'||panel==='restart'){panel=session.game.status==='playing'?null:'result';render();if(!panel)q(`[data-m3-index="${focused}"]`)?.focus({preventScroll:true});}else onExit();return;}const cell=event.target.closest('[data-m3-index]');if(!cell||locked||panel)return;const i=Number(cell.dataset.m3Index),delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-M3_WIDTH,ArrowDown:M3_WIDTH}[event.key];if(delta){event.preventDefault();if(m3Adjacent(i,i+delta)){focused=i+delta;board();q(`[data-m3-index="${focused}"]`).focus({preventScroll:true});}}else if(['Enter',' '].includes(event.key)){event.preventDefault();choose(i);}});
  return{
    show(next,context='为故乡带回重建材料'){session=next;shown=true;locked=false;chosen=null;hints=[];hammerMode=false;panel=next.game.status==='playing'?null:'result';root.hidden=false;root.classList.toggle('river-match',next.region==='river');q('#m3-purpose').textContent=context;render();status(next.game.goals.some(g=>g.kind==='mud')?'在泥地上消除棋子，清理地面。':'交换相邻棋子，三个相同即可消除。');if(!panel)q(`[data-m3-index="${focused}"]`)?.focus({preventScroll:true});},
    hide(){shown=false;root.hidden=true;panel=null;chosen=null;hints=[];hammerMode=false;},
    isBusy:()=>locked
  };
}
